import Foundation

/// A color ibtool converts by color management, as a document writes it: its color space
/// (`calibratedRGB`, `deviceRGB`, or the custom `displayP3`) and its components.
struct ConvertedColor: Hashable {
    static let spaces: Set = ["calibratedRGB", "deviceRGB", "displayP3"]
    let space: String
    let red: Double
    let green: Double
    let blue: Double

    init(_ space: String, _ red: Double, _ green: Double, _ blue: Double) {
        self.space = space
        self.red = red
        self.green = green
        self.blue = blue
    }
}

